import{_ as e,o as a,c as r,ae as o}from"./chunks/framework.Dh1jimFm.js";const g=JSON.parse('{"title":"Segment Statuses","description":"","frontmatter":{},"headers":[],"relativePath":"editor/segment-statuses.md","filePath":"editor/segment-statuses.md"}'),n={name:"editor/segment-statuses.md"};function s(d,t,i,h,l,c){return a(),r("div",null,t[0]||(t[0]=[o('<h1 id="segment-statuses" tabindex="-1">Segment Statuses <a class="header-anchor" href="#segment-statuses" aria-label="Permalink to &quot;Segment Statuses&quot;">​</a></h1><p>Every segment in Supervertaler carries two independent pieces of information:</p><ol><li><strong>Match origin</strong> — how the translation got there (TM match, machine translation, manual typing)</li><li><strong>Workflow status</strong> — where the segment is in the review cycle (draft, confirmed, approved)</li></ol><p>These are two separate dimensions. A segment can be a 100% TM match <em>and</em> confirmed — the match tells you where the translation came from, and the workflow status tells you whether a human has signed off on it.</p><hr><h2 id="workflow-statuses" tabindex="-1">Workflow Statuses <a class="header-anchor" href="#workflow-statuses" aria-label="Permalink to &quot;Workflow Statuses&quot;">​</a></h2><p>These track a segment&#39;s progress through the translation and review cycle.</p><table tabindex="0"><thead><tr><th>Status</th><th>Icon</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Not started</strong></td><td>❌</td><td>No translation yet. The target is empty.</td></tr><tr><td><strong>Draft</strong></td><td>✏️</td><td>Has a translation, but it has not been confirmed yet. This includes segments filled by AI, TM pre-translation, or manual typing that the translator has not yet explicitly confirmed.</td></tr><tr><td><strong>Confirmed</strong></td><td>✔</td><td>The translator has explicitly confirmed the translation (Ctrl+Enter). The segment is saved to TM at this point.</td></tr><tr><td><strong>Proofread</strong></td><td>🟪</td><td>A reviewer has checked and approved the translation.</td></tr><tr><td><strong>Approved</strong></td><td>⭐</td><td>Final sign-off. The translation has passed all review stages.</td></tr><tr><td><strong>Rejected</strong></td><td>🚫</td><td>A reviewer has rejected the translation. It needs to be revised.</td></tr><tr><td><strong>Locked</strong></td><td>🔒</td><td>The segment cannot be edited. Typically used for non-translatable content or segments that must not be changed.</td></tr></tbody></table><h3 id="how-confirmation-works" tabindex="-1">How confirmation works <a class="header-anchor" href="#how-confirmation-works" aria-label="Permalink to &quot;How confirmation works&quot;">​</a></h3><p>When you press <strong>Ctrl+Enter</strong>, the current segment is marked as <strong>Confirmed</strong> and the cursor moves to the next unconfirmed segment. Only confirmed segments are saved to Translation Memory.</p><p>If you go back and edit a confirmed segment, it automatically drops back to <strong>Draft</strong> until you re-confirm it. This prevents accidental TM entries from half-finished edits.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You can also change a segment&#39;s status manually via the right-click context menu, or by selecting segments and using the <strong>Status</strong> menu in the menu bar.</p></div><hr><h2 id="match-origins" tabindex="-1">Match Origins <a class="header-anchor" href="#match-origins" aria-label="Permalink to &quot;Match Origins&quot;">​</a></h2><p>Match origins tell you how the translation was initially obtained, before anyone reviewed it. They appear as the segment status when the segment has been pre-translated but not yet confirmed.</p><table tabindex="0"><thead><tr><th>Status</th><th>Icon</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>PM (102%)</strong></td><td>⭐</td><td><strong>Perfect Match.</strong> The segment matches a TM entry with identical context (surrounding segments). The highest level of TM confidence.</td></tr><tr><td><strong>CM (101%)</strong></td><td>💎</td><td><strong>Context Match.</strong> A 100% TM match where the preceding segment context also matches.</td></tr><tr><td><strong>TM 100%</strong></td><td>✅</td><td><strong>Exact Match.</strong> The source text matches a TM entry exactly, without additional context confirmation.</td></tr><tr><td><strong>TM Fuzzy</strong></td><td>🔶</td><td><strong>Fuzzy Match.</strong> The source partially matches a TM entry (typically 75-99%). The translation will need editing.</td></tr><tr><td><strong>MT</strong></td><td>🤖</td><td><strong>Machine Translation.</strong> Generated by an MT engine or AI model.</td></tr><tr><td><strong>Repetition</strong></td><td>🔁</td><td><strong>Internal Repetition.</strong> The same source text appears elsewhere in the project and the translation was auto-propagated.</td></tr><tr><td><strong>Pre-translated</strong></td><td>🤖</td><td>Generic pre-translation from an unspecified source.</td></tr></tbody></table><h3 id="what-happens-when-you-confirm-a-match" tabindex="-1">What happens when you confirm a match <a class="header-anchor" href="#what-happens-when-you-confirm-a-match" aria-label="Permalink to &quot;What happens when you confirm a match&quot;">​</a></h3><p>When you confirm a segment, its status changes from its match origin (e.g. &quot;CM 101%&quot;) to <strong>Confirmed</strong>. The match percentage is preserved internally, but the status icon now reflects the workflow state rather than the match type. This is the same behavior as in Trados Studio and memoQ.</p><hr><h2 id="mapping-to-other-cat-tools" tabindex="-1">Mapping to Other CAT Tools <a class="header-anchor" href="#mapping-to-other-cat-tools" aria-label="Permalink to &quot;Mapping to Other CAT Tools&quot;">​</a></h2><p>Supervertaler&#39;s statuses map cleanly to Trados Studio and memoQ. When you import a file from either tool, both the match origin and the workflow status are preserved. When you export back, statuses are mapped to the correct values for each tool.</p><h3 id="workflow-statuses-1" tabindex="-1">Workflow statuses <a class="header-anchor" href="#workflow-statuses-1" aria-label="Permalink to &quot;Workflow statuses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Supervertaler</th><th>Trados Studio</th><th>memoQ</th></tr></thead><tbody><tr><td>Not started</td><td><em>(no translation)</em></td><td>Not started</td></tr><tr><td>Draft</td><td>Draft</td><td>Edited</td></tr><tr><td>Confirmed</td><td>Translated ✓</td><td>Confirmed</td></tr><tr><td>Proofread</td><td>Translation Approved</td><td>Reviewer 1 confirmed</td></tr><tr><td>Approved</td><td>Sign-off Approved</td><td>Reviewer 2 confirmed</td></tr><tr><td>Rejected</td><td>Translation Rejected</td><td>Rejected</td></tr><tr><td>Locked</td><td>Locked</td><td>Locked</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Trados naming quirk:</strong> In Trados Studio, &quot;Translated&quot; (green checkmark) actually means <em>confirmed by the translator</em>. This is equivalent to Supervertaler&#39;s <strong>Confirmed</strong>. Trados &quot;Draft&quot; is equivalent to Supervertaler&#39;s <strong>Draft</strong>.</p></div><h3 id="match-origins-1" tabindex="-1">Match origins <a class="header-anchor" href="#match-origins-1" aria-label="Permalink to &quot;Match origins&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Supervertaler</th><th>Trados Studio</th><th>memoQ</th></tr></thead><tbody><tr><td>PM (102%)</td><td>Perfect Match</td><td>102% (double context)</td></tr><tr><td>CM (101%)</td><td>Context Match</td><td>101% (context match)</td></tr><tr><td>TM 100%</td><td>Exact Match (100%)</td><td>100%</td></tr><tr><td>TM Fuzzy</td><td>Fuzzy Match</td><td>Fuzzy (75-99%)</td></tr><tr><td>MT</td><td>Machine Translation (NMT/AT)</td><td>MT</td></tr><tr><td>Repetition</td><td>Repetition (auto-propagated)</td><td>Repetition</td></tr></tbody></table><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./editing-confirming.html">Editing &amp; Confirming</a></li><li><a href="./translation-grid.html">The Translation Grid</a></li><li><a href="./../cat-tools/overview.html">CAT Tool Integration</a></li><li><a href="./../cat-tools/trados.html">Trados Studio Workflow</a></li><li><a href="./../cat-tools/memoq.html">memoQ Workflow</a></li></ul>',29)]))}const u=e(n,[["render",s]]);export{g as __pageData,u as default};
